<?php
require_once __DIR__.'/../includes/bootstrap.php';
$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1");$st->execute([$id]);$p=$st->fetch();
if(!$p){http_response_code(404);$pageTitle='Product not found';require __DIR__.'/../includes/header.php';echo '<div class="empty-state"><h2>Product not found</h2><a href="/lakshmi-electricals/products/index.php">Back to products</a></div>';require __DIR__.'/../includes/footer.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$qty=max(1,min(100,(int)($_POST['quantity']??1)));if((int)$p['stock_quantity']<$qty){flash('Requested quantity is not currently available.','error');}else{$_SESSION['cart'][$id]=min(100,(int)($_SESSION['cart'][$id]??0)+$qty);flash('Product added to cart.');}redirect('/lakshmi-electricals/cart/index.php');}
$pageTitle=$p['name'].' | Lakshmi Electricals';require __DIR__.'/../includes/header.php';
?>
<div class="detail-layout"><div class="detail-image"><?php if($p['image_path']): ?><img src="/lakshmi-electricals/<?= e($p['image_path']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span><?= e(strtoupper(substr($p['name'],0,1))) ?></span><?php endif; ?></div><div class="detail-copy"><span class="eyebrow"><?= e($p['category_name']) ?></span><h1><?= e($p['name']) ?></h1><?php if($p['brand']): ?><p>Brand: <?= e($p['brand']) ?></p><?php endif; ?><p><?= nl2br(e($p['description'])) ?></p><?php if($p['specifications']): ?><p><strong>Specifications:</strong> <?= nl2br(e($p['specifications'])) ?></p><?php endif; ?><h2 class="price"><?= $p['price']!==null?money($p['price']).($p['unit']?' / '.e($p['unit']):''):'Price on enquiry' ?></h2><p><?= (int)$p['stock_quantity']>0?'Available stock: '.(int)$p['stock_quantity'].' '.e($p['unit']):'Currently unavailable' ?></p><?php if((int)$p['stock_quantity']>0): ?><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Quantity<input type="number" name="quantity" value="1" min="1" max="<?= min(100,(int)$p['stock_quantity']) ?>"></label><button class="btn btn-gold">Add to cart</button></form><?php endif; ?><a class="btn btn-outline" target="_blank" rel="noopener" href="https://wa.me/919362070460?text=<?= rawurlencode('Hello, I would like to enquire about '.$p['name'].'.') ?>">Enquire on WhatsApp</a></div></div>
